pago com Meta Ads: gestor de anúncios, tipos de campanha, segmentação e métricas."},{"code":"14181095","playlist_id":"PL8mEkeR6KxctwMrpwLY7RgKgiL6IivgmC","ord":1,"confidence":"média","level":"superior","match":"Derivativos e hedge: futuros, swaps (incluindo cambial) e cobertura de risco, com os produtos de gestão de risco da UC."},{"code":"14181095","playlist_id":"PLpDoIofcp9Y7_IRSU7Nm8RyUEZ9HTf33v","ord":2,"confidence":"média","level":"introdutório","match":"Introdução ao mercado de derivativos: termo, futuros, opções e swaps."},{"code":"15161099","playlist_id":"PL28H-AQmelQNsxIqv7PebRsG2G-IHLhA4","ord":1,"confidence":"alta","level":"superior","match":"Critérios de avaliação: VPL/VAL, TIR, payback (tema 3)."},{"code":"15161099","playlist_id":"PLnx4ioejmfR3E08_tbdzf7hgUHT4EcK3W","ord":2,"confidence":"média","level":"superior","match":"VAL e TIR na análise da viabilidade e comparação de projetos."},{"code":"15161051","playlist_id":"PLTjWXFmeozbmArk7LdGoQYHU3UpRSQ88N","ord":1,"confidence":"média","level":"superior","match":"Teorias da internacionalização (Uppsala, paradigma eclético, redes) e processo de exportação (temas 3, 5, 8)."},{"code":"15161101","playlist_id":"PLIIW4N3aCKkRQkwGfCF2kcV8SCHBwYlCX","ord":1,"confidence":"média","level":"superior (introdutório)","match":"Marketing de relacionamento em 8 aulas (temas 1–2)."},{"code":"15161109","playlist_id":"PLWZ9pSn_wvWDjvJOYuyuXost78SzB3wwQ","ord":1,"confidence":"média","level":"introdutório","match":"Curso \"Copywriting, Storytelling e Narrativa\": narrativa estratégica e de marca, storytelling aplicado ao digital, posicionamento."},{"code":"15161109","playlist_id":"PLm7y-Z-ustqiIdVXz-nTuMkuoDWBKKbTM","ord":2,"confidence":"média","level":"superior","match":"Masterclasses do Clube do UX Writing: tom e voz, linguagem simples, arquitetura da informação e acessibilidade na escrita para interfaces digitais."},{"code":"14181093","playlist_id":"PLxI8Can9yAHdphItaZo26a2rLM8t0n6KM","ord":1,"confidence":"alta","level":"superior","match":"Disciplina da UNIVESP \"Planejamento e ferramentas de gestão estratégica\" (2025): planeamento, análise estratégica e ferramentas."},{"code":"14181093","playlist_id":"PLxI8Can9yAHetpjk8q5ZDjtGZeSk97_iP","ord":2,"confidence":"média","level":"superior","match":"Disciplina da UNIVESP \"Estratégia e Governança\" (Eixo de Negócios)."}]
$fpl$::jsonb) AS x(code text,playlist_id text,ord integer,confidence text,level text,match text);

DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>43 OR (SELECT count(DISTINCT code) FROM _u)<>43
 OR (SELECT sum(ects) FROM _u WHERE option_group IS NULL)<>170 OR (SELECT count(*) FROM _u WHERE option_group IS NULL)<>33
 OR (SELECT count(*) FROM _u WHERE option_group='Opção I')<>5 OR (SELECT count(*) FROM _u WHERE option_group='Opção II')<>5
 OR EXISTS(SELECT 1 FROM _u WHERE option_group IS NOT NULL AND ects<>5)
 OR EXISTS(SELECT 1 FROM _u WHERE jsonb_array_length(placements)<>1 OR placements->0->>'specialization'<>'Tronco Comum'
     OR (placements->0->>'role'='mandatory')<>(option_group IS NULL))
 OR (SELECT count(*) FROM _p)<>50 OR (SELECT count(*) FROM _pl)<>55 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN ('alta','média'))
 THEN RAISE EXCEPTION 'Unexpected Marketing manifest counts or ECTS (expected 180 = 170 + 5 + 5)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='LMKT' OR slug='marketing' OR (external_source='ualg_official' AND external_id='1516'))
 AND id<>md5('facodi:ualg:1516:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses LMKT, marketing or UAlg 1516; reconcile manually'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.curricular_units WHERE slug LIKE 'marketing-uc-%' AND course_id<>md5('facodi:ualg:1516:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses marketing-uc- slugs; reconcile manually'; END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
VALUES(md5('facodi:ualg:1516:course')::uuid,'course','Licenciatura em Marketing','facodi-course-marketing',
 'Licenciatura da Escola Superior de Gestão, Hotelaria e Turismo da Universidade do Algarve, com 180 ECTS em três anos. Fundamentos e políticas de marketing, comportamento do consumidor, estudos de mercado, comunicação, publicidade, marketing digital e comércio eletrónico, com gestão, finanças e métodos quantitativos.','[]'::jsonb,ARRAY['Marketing','Comportamento do consumidor','Estudos de mercado','Marketing digital','Publicidade'],ARRAY['Marketing'],
 'pt','active',true,'import','https://www.ualg.pt/curso/1516','ualg:licenciatura:1516:course',
 jsonb_build_object('university_course_code','1516','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1516/plano',
 'source_quality','ualg_official_programme','curation_batch','facodi_ualg_1516_marketing_20261118'))
ON CONFLICT DO NOTHING;

INSERT INTO facodi.courses(id,learning_object_id,code,external_source,external_id,slug,title,normalized_title,summary,description_html,
 degree_type,language,school,source_url,plan_url,status,published,metadata,institution,ects_total,duration_semesters)
VALUES(md5('facodi:ualg:1516:course:record')::uuid,md5('facodi:ualg:1516:course')::uuid,'LMKT','ualg_official','1516','marketing',
 'Licenciatura em Marketing','Marketing','Licenciatura da Escola Superior de Gestão, Hotelaria e Turismo da Universidade do Algarve, com 180 ECTS em três anos. Fundamentos e políticas de marketing, comportamento do consumidor, estudos de mercado, comunicação, publicidade, marketing digital e comércio eletrónico, com gestão, finanças e métodos quantitativos.','<h2>Apresentação</h2><p>A licenciatura desenvolve estratégias, métodos e instrumentos de intervenção no âmbito do marketing: prever o comportamento dos agentes de mercado, implementar ações criativas e inovadoras e analisar informação quantitativa e financeira sobre o desempenho de mercados, produtos e serviços.</p><h2>Plano de estudos</h2><p>33 unidades curriculares obrigatórias, incluindo um estágio de 10 ECTS no último semestre, e dois grupos de opção no 3.º ano, Opção I e Opção II, com cinco alternativas cada. O 1.º ano dá as bases de marketing, gestão, economia, contabilidade, estatística, informática e inglês; o 2.º e o 3.º anos aprofundam o consumidor, os estudos de mercado, a comunicação e a publicidade, o marketing digital, os serviços, as vendas e o marketing internacional e relacional.</p><h2>Na FACODI</h2><p>Cada unidade curricular tem playlists abertas do YouTube escolhidas a partir do programa da ficha oficial da UC.</p>',
 'Licenciatura','pt','Escola Superior de Gestão, Hotelaria e Turismo','https://www.ualg.pt/curso/1516','https://www.ualg.pt/curso/1516/plano','active',true,
 jsonb_build_object('official_course_id','1516','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1516/plano',
 'official_program_verified',true,'official_ects_total',180,'official_unit_count',43,'mandatory_unit_count',33,
 'curriculum_contains_elective_alternatives',true,'alternative_pathways_not_additive',true,
 'teaching_language','Português','source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1516_marketing_20261118'),
 'Universidade do Algarve',180,6)
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
SELECT md5('facodi:ualg:1516:uc:'||u.code)::uuid,'curricular_unit',u.title,'facodi-uc-marketing-'||u.code,u.summary,'[]'::jsonb,
 u.topics,ARRAY[u.title],'pt','active',true,'import','https://www.ualg.pt/curso/1516/plano','ualg:1516:uc:'||u.code,
 jsonb_build_object('university_course_code','1516','unit_code',u.code,'official_academic_year','2026/27',
 'official_fuc_url',u.fuc_url,'detailed_fuc_checked',true,'study_topics',to_jsonb(u.topics),'curation_batch','facodi_ualg_1516_marketing_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

-- Códigos partilhados com outro curso (LGEST): registo próprio neste curso; o slug leva prefixo só se o código já for slug de outra UC.
INSERT INTO facodi.curricular_units(id,learning_object_id,course_id,code,external_source,external_id,slug,title,normalized_title,summary,
 description_html,year,semester,ects,position,language,source_url,plan_url,status,published,metadata)
SELECT md5('facodi:ualg:1516:uc:record:'||u.code)::uuid,md5('facodi:ualg:1516:uc:'||u.code)::uuid,md5('facodi:ualg:1516:course:record')::uuid,
 u.code,'ualg_official','1516:'||u.code,
 CASE WHEN EXISTS(SELECT 1 FROM facodi.curricular_units o WHERE o.slug=u.code AND o.course_id<>md5('facodi:ualg:1516:course:record')::uuid)
 THEN 'marketing-uc-'||u.code ELSE u.code END,
 u.title,u.title,u.summary,'<p>'||u.summary||'</p><p><strong>Temas:</strong> '||array_to_string(u.topics,'; ')||'.</p>',
 u.year,u.semester,u.ects,u.position,'pt','https://www.ualg.pt/curso/1516/plano','https://www.ualg.pt/curso/1516/plano','active',true,
 jsonb_build_object('course_code','LMKT','official_course_id','1516','official_unit_code',u.code,'academic_year','2026/27',
 'official_plan_url','https://www.ualg.pt/curso/1516/plano','official_fuc_url',u.fuc_url,'detailed_fuc_checked',true,
 'official_code_checked',true,'official_ects_checked',true,'official_semester_checked',true,'offered_in_both_semesters',false,
 'is_elective_option',u.option_group IS NOT NULL,'official_option_group',u.option_group,
 'official_code_shared_with_course',u.shared_code_with,
 'curriculum_placements',u.placements,'study_topics',to_jsonb(u.topics),'source_quality','ualg_official_structure',
 'curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1516_marketing_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

